"""Checks on the data the slide deck loads (generated by deck/scripts/export_data.py)."""

from __future__ import annotations

import itertools
import json
import math
from pathlib import Path
from typing import Any

import pytest

ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "deck" / "src" / "data"
NAMES = [
    "baselines",
    "privacy_utility",
    "membership",
    "update_leakage",
    "poisoning",
    "free_riding",
    "gossip",
    "participation",
    "sensitivity",
    "ledger_audit",
    "social_graph",
    "dataset_card",
    "flower_parity",
    "calibration",
]
GENERATED = ["results", "code", "accounting_grid", "facts", "merkle_vectors"]
FORBIDDEN_KEYS = {"user_id", "business_id", "review_id"}


def _load(name: str) -> Any:
    path = DATA / f"{name}.json"
    if not path.exists():
        pytest.fail(f"{path} is missing: run `uv run python deck/scripts/export_data.py`")
    return json.loads(path.read_text(encoding="utf-8"))


def _finite(value: Any) -> Any:
    """Same normalisation as the exporter: non-finite floats become None."""
    if isinstance(value, float) and not math.isfinite(value):
        return None
    if isinstance(value, dict):
        return {k: _finite(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_finite(v) for v in value]
    return value


def _keys(value: Any):
    if isinstance(value, dict):
        for k, v in value.items():
            yield k
            yield from _keys(v)
    elif isinstance(value, list):
        for v in value:
            yield from _keys(v)


@pytest.mark.parametrize("name", NAMES)
def test_results_copy_source_files(name: str) -> None:
    results = _load("results")
    source = json.loads((ROOT / "results" / f"{name}.json").read_text(encoding="utf-8"))
    assert results[name] == _finite(source)


def test_code_excerpt_matches_file() -> None:
    entry = _load("code")["models/hybrid.py::user_loss"]
    lines = (ROOT / entry["file"]).read_text(encoding="utf-8").splitlines()
    assert entry["file"] == "src/prism/models/hybrid.py"
    assert entry["source"] == "\n".join(lines[entry["start"] - 1 : entry["end"]])
    assert "report/build.py" not in " ".join(k.split("::")[0] for k in _load("code"))


def test_documented_fact_quotes_are_in_their_files() -> None:
    facts = _load("facts")
    documented = json.loads(
        (ROOT / "deck" / "scripts" / "documented_facts.json").read_text(encoding="utf-8")
    )
    assert documented
    for key in documented:
        fact = facts[key]
        text = (ROOT / fact["source"]).read_text(encoding="utf-8")
        assert fact["quote"] in text, key
    for key in ("runs.records", "runs.with_code_hash", "runs.engine_hash", "tests.count"):
        assert key in facts
    assert facts["speed.before_s"]["value"] == 171
    assert facts["speed.after_s"]["value"] == 29


def test_accounting_grid() -> None:
    grid = _load("accounting_grid")
    eps = grid["epsilon"]
    assert (len(eps), len(eps[0]), len(eps[0][0])) == (2, 6, 14)
    assert grid["accountant"] == "pld"
    assert grid["users"] == 9913
    assert grid["delta"] == pytest.approx(1 / (10 * 9913))
    for rate_block in eps:
        for row in rate_block:
            assert all(v is not None for v in row)
            assert all(a > b for a, b in itertools.pairwise(row))
    ri, ti, ni = grid["rates"].index(0.05), grid["rounds"].index(400), grid["noise"].index(0.92)
    assert 7 <= eps[ri][ti][ni] <= 9


def test_merkle_vectors_are_consistent() -> None:
    vectors = _load("merkle_vectors")
    assert vectors["leaf_hash"] and vectors["node_hash"]
    from prism.ledger.merkle import leaf_hash, merkle_root, verify_inclusion

    for count, v in vectors["vectors"].items():
        leaves = [s.encode("utf-8") for s in v["leaves_utf8"]]
        assert len(leaves) == int(count)
        assert [leaf_hash(x).hex() for x in leaves] == v["leaf_hashes"]
        assert merkle_root(leaves).hex() == v["root"]
        i = v["proof"]["index"]
        assert i == int(count) // 2
        proof = [bytes.fromhex(h) for h in v["proof"]["hashes"]]
        assert verify_inclusion(leaves[i], i, len(leaves), proof, bytes.fromhex(v["root"]))
    assert sorted(int(c) for c in vectors["vectors"]) == [1, 2, 3, 5, 8, 13]


def test_no_identifier_keys_and_size() -> None:
    total = 0
    for name in GENERATED:
        path = DATA / f"{name}.json"
        _load(name)
        total += path.stat().st_size
        text = path.read_text(encoding="utf-8")
        seen: list[str] = []
        json.loads(text, parse_constant=seen.append)
        assert not seen, f"{name} has non-finite values {seen}"
        bad = FORBIDDEN_KEYS & set(_keys(json.loads(text)))
        assert not bad, f"{name} has identifier keys {bad}"
    assert total < 3 * 1024 * 1024
